-- 1단계: 기존 payments FK 참조 제거
DELETE FROM payments
WHERE reservation_id IN (
  SELECT id FROM reservations WHERE guest_name IS NULL
);

-- 2단계: 기존 미등록 데이터 삭제
DELETE FROM reservations WHERE guest_name IS NULL;

